use std::sync::mpsc;
use std::time::{Duration,Instant};
#[repr(C)] struct Timespec { seconds:i64,nanos:i64 }
unsafe extern "C" { fn clock_gettime(clock:i32,time:*mut Timespec)->i32; }
fn cpu_ns()->u64 { let mut t=Timespec{seconds:0,nanos:0};assert_eq!(unsafe{clock_gettime(3,&mut t)},0);(t.seconds as u64)*1_000_000_000+t.nanos as u64 }
fn main(){
 for spin in [0u64,16,16,0,0,16,16,0] {
  let (tx,rx)=mpsc::channel::<u64>();let (reply,done)=mpsc::channel::<u64>();
  let worker=std::thread::spawn(move||{
   let cpu=cpu_ns();let mut previous=false;let mut hot_streak=0u32;
   loop {
    let wait_started=Instant::now();
    let value=if previous&&spin>0&&hot_streak>=2 {
     let until=Instant::now()+Duration::from_micros(spin);
     loop {match rx.try_recv(){Ok(v)=>break Some(v),Err(mpsc::TryRecvError::Disconnected)=>break None,Err(mpsc::TryRecvError::Empty)=>{if Instant::now()>=until {break rx.recv().ok()}std::hint::spin_loop();}}}
    }else{rx.recv().ok()};
    let Some(value)=value else {break};
    hot_streak=if wait_started.elapsed()<=Duration::from_micros(64){hot_streak.saturating_add(1)}else{0};
    previous=true;reply.send(value).unwrap();
   }
   cpu_ns()-cpu
  });
  let cpu=cpu_ns();let mut times=Vec::with_capacity(20000);
  for i in 0..20000 {let start=Instant::now();tx.send(i).unwrap();assert_eq!(done.recv().unwrap(),i);times.push(start.elapsed().as_nanos() as u64);}
  let caller=cpu_ns()-cpu;drop(tx);let worker_cpu=worker.join().unwrap();let total:u64=times.iter().sum();times.sort_unstable();
  println!("{{\"spin_us\":{},\"iterations\":20000,\"mean_ns\":{},\"p99_ns\":{},\"caller_cpu_ns_per_call\":{},\"worker_cpu_ns_per_call\":{}}}",spin,total/20000,times[19799],caller/20000,worker_cpu/20000);
 }
}

